"""Offline, source-linked model review. No generated architectural imagery."""
from pathlib import Path
import base64, csv, html, io, json, os, shutil
from PIL import Image, ImageDraw, ImageFont
CASE=Path(__file__).resolve().parents[1];ROOT=CASE.parents[1]
OUT=ROOT/'deliverables/guangzhou_customs_v1';STEM='Guangzhou_Customs_HAF_V1';RUN='V1_r04'
LABEL={'overview':'整体 · 前侧斜视','night':'整体 · 夜间试验','front':'正面','rear':'背面','left':'左侧','right':'右侧','top':'俯视','crown':'钟冠 · 斜侧','crown_front':'钟冠 · 正面近景','entrance':'入口 · 成对柱廊','entrance_night':'入口 · 夜间','podium_rear':'基座 · 后侧双玻璃体','facade':'窗墙 · 近景','section':'剖切 · 楼板与局部内饰'}
Q={'se':'东南','sw':'西南','ne':'东北','nw':'西北'}
for q,name in Q.items():
    for mode in ['day','night']:LABEL[q+'_'+mode]=name+' 45° · '+('日间' if mode=='day' else '夜间')

def uri(p,mime='image/png'):
    return 'data:'+mime+';base64,'+base64.b64encode(Path(p).read_bytes()).decode()

def photo(p):
    if not p.exists():return None
    im=Image.open(p).convert('RGB');im.thumbnail((1500,1800));b=io.BytesIO();im.save(b,'JPEG',quality=88)
    return 'data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode()

def contact_sheet(prev,mode):
    font_path=os.environ.get('HAF_CJK_FONT',str(ROOT/'support/fonts/NotoSansCJKsc-Regular.otf'))
    try:
        title=ImageFont.truetype(font_path,52);small=ImageFont.truetype(font_path,26);label=ImageFont.truetype(font_path,32)
    except OSError:
        title=small=label=ImageFont.load_default()
    bg='#15232a' if mode=='night' else '#f4f0e7';fg='#f4efe5' if mode=='night' else '#243b40'
    panelw,panelh=900,1125;pad=24;w=panelw*4+pad*5;h=panelh+205
    im=Image.new('RGB',(w,h),bg);d=ImageDraw.Draw(im)
    d.text((pad,22),'广州新海关 · HAF V1 / '+('夜间四向' if mode=='night' else '日间四向'),font=title,fill=fg)
    d.text((pad,92),'SE · SW · NE · NW  |  模型坐标：东 +X / 北 −Z；地理北未标定  |  最终 NBT 几何预览',font=small,fill=fg)
    for i,(q,name) in enumerate(Q.items()):
        frame=Image.open(prev/(q+'_'+mode+'.png')).convert('RGB');frame.thumbnail((panelw,panelh))
        x=pad+(panelw+pad)*i
        im.paste(frame,(x+(panelw-frame.width)//2,160))
        d.text((x,125),name+' 45°',font=label,fill=fg)
    im.save(OUT/(STEM+'_Four_Views_'+mode.title()+'.png'))


CSS=r'''
:root{--ink:#203c42;--muted:#5f7276;--paper:#f6f3ec;--line:#d8dfd9;--accent:#9b743d;--panel:#fffdf8}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.75 system-ui,-apple-system,"Noto Sans CJK SC",sans-serif}header{padding:64px max(6vw,24px) 36px;background:#203c42;color:#fff8e9}header small{letter-spacing:.18em;color:#d1bc92}h1{font-weight:600;font-size:clamp(36px,6vw,76px);line-height:1.15;letter-spacing:-.04em;margin:20px 0}header p{max-width:780px;color:#dce2dd}nav{position:sticky;top:0;z-index:5;display:flex;gap:24px;overflow:auto;white-space:nowrap;padding:14px max(6vw,24px);background:#f6f3ecf5;border-bottom:1px solid var(--line)}nav a{color:var(--ink);text-decoration:none;font-size:14px}main{max-width:1440px;padding:0 30px;margin:auto}section{padding:56px 0;border-bottom:1px solid var(--line);scroll-margin-top:68px}h2{font-size:28px;letter-spacing:-.03em;font-weight:600;margin:0 0 24px}h3{font-size:19px;margin:0 0 12px}p{margin:10px 0 18px}a{color:#486f7a}button,select,input,textarea{font:inherit;color:inherit}button,.download{border:1px solid var(--ink);border-radius:5px;padding:8px 16px;background:transparent;cursor:pointer;text-decoration:none}button:hover,.download:hover{background:#e4ebe5}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #ac883e;outline-offset:3px}.primary{background:var(--ink);color:#fffdf5}.primary:hover{background:#345760}select,input,textarea{border:1px solid #b4c4c4;border-radius:4px;background:#fffdf8;padding:8px 12px;max-width:100%}textarea{width:100%;min-height:110px}label{display:block;font-size:14px;color:var(--muted);margin-bottom:6px}.toolbar{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-bottom:20px}.toolbar label{margin:0}.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}.three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.card{padding:22px;border:1px solid var(--line);background:var(--panel);border-radius:8px}.metric{font-size:32px;line-height:1.3;display:block;margin-bottom:6px;font-weight:600}.muted{color:var(--muted);font-size:14px}.note{border-left:3px solid #af8b54;padding:12px 18px;background:#eee8d9;font-size:14px}.hero{display:grid;grid-template-columns:2.2fr 1fr;gap:32px;align-items:center}.hero img{width:100%;max-height:1160px;object-fit:contain;cursor:zoom-in}.hero aside{padding:22px;border-left:1px solid var(--line)}.quad-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}.quad-grid img{width:100%;cursor:zoom-in}.compare img{width:100%;height:670px;object-fit:contain;cursor:zoom-in;background:#e4eae5}.thumbs{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.thumbs button{font-size:13px;padding:5px 10px;border-color:#aabdbd}.thumbs button[aria-pressed=true]{background:var(--ink);color:#fff}.viewer{background:#e3e9e5;border-radius:8px;overflow:hidden}.viewer img{display:block;width:100%;height:min(1000px,86vh);object-fit:contain;cursor:zoom-in}.caption{padding:18px 24px;background:var(--panel)}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:12px 10px;border-bottom:1px solid var(--line);vertical-align:top;text-align:left}th{background:#e8eee8;color:#314a50}pre{font-size:13px;background:#e8ede7;padding:20px;overflow:auto;white-space:pre-wrap;border-radius:6px}.tag{display:inline-block;font-size:12px;padding:2px 8px;border:1px solid var(--line);border-radius:3px;margin-right:5px;color:var(--muted)}details{border-bottom:1px solid var(--line);padding:12px 0}summary{cursor:pointer;font-weight:600}.feedback-row{padding:15px;border:1px solid var(--line);margin:12px 0;border-radius:6px;white-space:pre-wrap}.feedback-row button{float:right;font-size:12px}footer{padding:42px 6vw;color:var(--muted);font-size:13px}dialog{padding:0;border:0;width:96vw;max-width:96vw;height:94vh;max-height:94vh;background:var(--paper)}dialog::backdrop{background:#061015d9}.zoom-head{position:sticky;top:0;display:flex;gap:12px;align-items:center;padding:12px 20px;background:var(--paper);z-index:2}.zoom-head strong{margin-right:auto}.zoom-scroll{height:calc(100% - 70px);overflow:auto;text-align:center}.zoom-scroll img{max-width:100%;max-height:100%;object-fit:contain}.sources li{margin:10px 0;word-break:break-word}.large{font-size:20px;line-height:1.65}.feedback-grid{display:grid;grid-template-columns:2fr 2fr 1fr;gap:18px}@media(max-width:800px){main{padding:0 18px}.hero,.two,.three{grid-template-columns:1fr}.hero aside{border-left:0;border-top:1px solid var(--line)}.quad-grid{gap:12px}.compare img{height:440px}section{padding:38px 0}nav{gap:18px}.feedback-grid{grid-template-columns:1fr}.zoom-head{flex-wrap:wrap}.zoom-head button{font-size:12px;padding:5px 8px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
'''

JS=r'''
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);
const storage='haf-guangzhou-customs-v1-feedback-'+D.hash.slice(0,12);let current='overview',items=[];
function zoom(src,title){$('zoomImg').src=src;$('zoomTitle').textContent=title;$('zoomImg').style.maxWidth='100%';$('zoomImg').style.maxHeight='100%';$('zoom').showModal()}
$('zoomClose').onclick=()=>$('zoom').close();$('zoomActual').onclick=()=>{const actual=$('zoomImg').style.maxWidth==='none';$('zoomImg').style.maxWidth=actual?'100%':'none';$('zoomImg').style.maxHeight=actual?'100%':'none'};
document.querySelectorAll('[data-zoom]').forEach(e=>e.onclick=()=>zoom(e.src,e.alt));
function quads(){for(const q of ['se','sw','ne','nw']){const v=D.views[q+'_'+$('quadMode').value];$('quad_'+q).src=v.src;$('quad_'+q).alt=v.label;$('quad_'+q).onclick=()=>zoom(v.src,v.label)}}$('quadMode').onchange=quads;quads();
function show(k){current=k;const v=D.views[k];$('mainImage').src=v.src;$('imageTitle').textContent=v.label;$('imageNote').textContent=(k.includes('night')?'夜间为游戏灯光方案；未取得可信同楼夜景照。':'最终 NBT 几何预览；未加载 Minecraft 纹理。')+' 点击放大，可切换原始尺寸。';document.querySelectorAll('#viewButtons button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.key===k?'true':'false'))}
for(const [k,v] of Object.entries(D.views)){let b=document.createElement('button');b.type='button';b.textContent=v.label;b.dataset.key=k;b.onclick=()=>show(k);$('viewButtons').append(b);let op=document.createElement('option');op.value=k;op.textContent=v.label;$('fbView').append(op)}show(current);$('mainImage').onclick=()=>zoom(D.views[current].src,D.views[current].label);
function compare(){const v=D.comparisons[$('comparePart').value];$('refTitle').textContent=v.title;$('refImage').src=v.photo||D.views[v.view].src;$('refImage').alt=v.photo?v.title:'原图未收入源码包，请查看交付HTML';$('modelImage').src=D.views[v.view].src;$('modelTitle').textContent=D.views[v.view].label;$('compareNote').textContent=v.note;$('refSource').href=v.url;$('refSource').textContent=v.source;$('refImage').onclick=()=>zoom($('refImage').src,$('refImage').alt);$('modelImage').onclick=()=>zoom($('modelImage').src,D.views[v.view].label)}$('comparePart').onchange=compare;compare();
function download(name,value,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([value],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
$('downloadMaterials').onclick=()=>download(D.stem+'_Materials.csv','\uFEFF'+D.material_csv,'text/csv;charset=utf-8');
for(const c of D.components){let op=document.createElement('option');op.value=c.id;op.textContent=c.label;$('fbPart').append(op)}
try{const old=JSON.parse(localStorage.getItem(storage)||'[]');if(Array.isArray(old))items=old}catch(e){$('fbStatus').textContent='本机存储不可用，仍可填写并导出JSON。'}
function persist(){try{localStorage.setItem(storage,JSON.stringify(items))}catch(e){$('fbStatus').textContent='未能保存到本机，请立即导出反馈JSON。'}}
function list(){ $('feedbackList').replaceChildren();$('feedbackCount').textContent='已记录 '+items.length+' 条反馈';items.forEach((r,i)=>{const div=document.createElement('div');div.className='feedback-row';const del=document.createElement('button');del.type='button';del.textContent='删除';del.onclick=()=>{items.splice(i,1);persist();list()};const t=document.createElement('span');t.textContent=r.component_id+' · '+r.view+'\n'+r.problem+'\n希望：'+r.proposed_change;div.append(del,t);$('feedbackList').append(div)})}list();
$('feedbackForm').onsubmit=e=>{e.preventDefault();const problem=$('fbProblem').value.trim(),change=$('fbChange').value.trim();if(!problem||!change){$('fbStatus').textContent='请填写观察与希望调整的内容。';return}items.push({baseline_run:D.run,baseline_nbt_sha256:D.hash,component_id:$('fbPart').value,view:$('fbView').value,priority:$('fbPriority').value,problem,proposed_change:change,reference_url:$('fbEvidence').value.trim(),created_at:new Date().toISOString()});persist();list();$('fbStatus').textContent='已记录；没有修改模型。';$('fbProblem').value='';$('fbChange').value=''};
$('exportFeedback').onclick=()=>download(D.stem+'_Feedback.json',JSON.stringify({case:'guangzhou_customs',baseline_run:D.run,baseline_nbt_sha256:D.hash,items},null,2),'application/json');
'''


def main():
    OUT.mkdir(parents=True,exist_ok=True);run=CASE/'runs'/RUN;prev=CASE/'review/previews'/RUN
    m=json.loads((run/'manifest.json').read_text());qa=json.loads((CASE/'validation/acceptance.json').read_text());imp=json.loads((run/'import_pack/import_manifest.json').read_text());evidence=json.loads((CASE/'research/component_evidence.json').read_text())
    materials=(run/'materials.csv').read_text(encoding='utf-8-sig');counts=m['room_lighting_counts']
    views={k:dict(src=uri(prev/(k+'.png')),label=v) for k,v in LABEL.items()}
    compar={
       'mass':dict(title='实景正面 · img-nc-08',photo=photo(CASE/'research/images/img-nc-08.jpg'),view='front',url='https://www.baike.com/wikiid/1624267802059567592',source='快懂百科条目照片；摄影者、日期与授权未核',note='观察中央抬高、左右肩部与窗列节奏。实景透视与模型正投影不同，不能直接拿像素比当测绘尺寸。'),
       'crown':dict(title='实景钟冠局部 · img-nc-07 的裁剪',photo=photo(CASE/'research/regions/img-nc-07_crown.jpg'),view='crown_front',url='https://you.m.autohome.com.cn/details/bigimage?from=1&img_index=12&pageIndex=1&seriesId=&tripId=130651',source='汽车之家游记原图；此裁剪不增加独立视角数量',note='小方钟室、浅弧顶、细针、大拱窗与成对柱是识别重点。该尺度下省略罗马数字，采用四个主要刻度。'),
       'entrance':dict(title='实景入口 · img-nc-01',photo=photo(CASE/'research/images/img-nc-01.jpg'),view='entrance',url='https://news.sina.cn/sa/2006-09-08/detail-ikkntiam7761731.d.html',source='信息时报／新浪，2006-09-08',note='参考成对圆柱、平檐、台阶和后退玻璃门；真实字样未在小尺度中强行做成不可读像素。'),
       'rear':dict(title='实景高位斜侧 · img-nc-11',photo=photo(CASE/'research/images/img-nc-11.jpg'),view='ne_day',url='https://www.sohu.com/a/282204526_761259',source='中建四局华南，2018-12-15 回顾文章末节',note='采用中央向后凸体、低层屋顶和双玻璃盒。模型右侧大拱窗的方位映射仍待核实，完整背面没有测绘。')}
    parts={'tower.mass':'主塔比例','tower.front':'窗墙与幕墙','crown.arch':'大拱窗与柱列','clock':'钟室、弧顶与细针','podium':'基座与屋顶玻璃体','entrance':'入口与台阶','lighting':'日夜灯光','interior':'楼板与伪内饰'}
    data=dict(views=views,comparisons=compar,hash=m['sha256'],run=RUN,stem=STEM,material_csv=materials,components=[dict(id=k,label=v) for k,v in parts.items()])
    sections=[]
    def sec(id,title,body):sections.append(f'<section id="{id}"><h2>{title}</h2>{body}</section>')
    sec('result','01 / 先把这栋楼的性格做出来',f'''<div class="hero"><img data-zoom src="{views['overview']['src']}" alt="广州新海关 V1 整体模型"><aside><p class="large">浅色窗墙、中央大拱窗，和一座克制的小钟楼。</p><p>本轮沿用已有新海关资料包，制作花城大道83号这栋高层办公楼。先保留它的体量分段与前后关系，再加入窗洞、柱廊、檐口和局部内饰。</p><p><span class="metric">{m['non_air_blocks']:,}</span>实际非空气方块</p><p><span class="metric">22 张</span>全景、近景、俯视与剖切</p><p><span class="tag">HAF 0.2</span><span class="tag">V1 / r04</span><span class="tag">纯图片路线</span></p><p class="muted">这些是最终 NBT 的几何预览，未加载游戏纹理，不是游戏截图。</p></aside></div>''')
    quads=''.join(f'<article><h3>{label} 45°</h3><img id="quad_{q}" alt="{label}方向模型"></article>' for q,label in Q.items())
    sec('quadrants','02 / 四个 45°，一面都不省',f'''<div class="toolbar"><label for="quadMode">四向联动</label><select id="quadMode"><option value="day">日间</option><option value="night">夜间灯光试验</option></select><span class="muted">点击每一张可打开原始大图</span></div><div class="quad-grid">{quads}</div><p class="note">东南、西南、东北、西北按模型坐标标注：东 +X，北 −Z。四面共用中心、俯角、尺度和照明方向；真实地理北尚未标定。</p>''')
    options=''.join(f'<option value="{k}">{v["title"].split(" · ")[0]}</option>' for k,v in compar.items())
    sec('compare','03 / 对着照片看，哪些抓住了',f'''<div class="toolbar"><label for="comparePart">选择部位</label><select id="comparePart">{options}</select></div><div class="two compare"><article><h3 id="refTitle"></h3><img id="refImage" alt="实景参考"><p class="muted"><a id="refSource" target="_blank" rel="noopener"></a></p></article><article><h3 id="modelTitle"></h3><img id="modelImage" alt="对应模型视图"></article></div><p id="compareNote"></p><p class="muted">这是构件观察对照，不是相机标定后的误差测量。4张独立照片已实际查看；同图裁剪不算新的互证。资料数量没有六图上限。</p>''')
    sec('gallery','04 / 放大看钟冠、入口、窗洞和楼板','''<div id="viewButtons" class="thumbs"></div><div class="viewer"><img id="mainImage" alt="模型当前视图"><div class="caption"><strong id="imageTitle"></strong><p id="imageNote" class="muted"></p></div></div><p class="muted">剖切为查看内部而隐藏一侧几何；交付建筑本身保留完整围护。夜景仅用于观察本轮游戏灯光方案。</p>''')
    cards=[]
    for r in evidence:
        imgs='、'.join(i['id'] for i in r['images']) or '无实景内饰／夜景证据，属于方案'
        cards.append(f'<article class="card"><h3>{parts[r["component_id"]]}</h3><p>{html.escape(r["decision"])}</p><p class="muted">依据：{imgs}</p><details><summary>还缺什么</summary><p>{html.escape(r["uncertainty"])}</p></details></article>')
    sec('research','05 / 每个部位各用适合的证据','<div class="two">'+''.join(cards)+'</div><p>高位照片支持背面凸体与基座；高清正面用于钟冠和窗墙；入口另用近景。没有拿到SU或其他三维模型，本次没有模拟“模型融合”。照片之间建立了视角关系，但没有做正交拼接。</p>')
    sec('scale','06 / 尺度、材质与灯光的取舍',f'''<div class="three"><article class="card"><strong class="metric">137 格</strong><p>地面至针尖的试作包络，包含整个钟冠。不是已解决冲突的实测高度。</p></article><article class="card"><strong class="metric">77 格</strong><p>本版主塔宽度。主塔进深与中央凸体分别处理；比例来自照片解释。</p></article><article class="card"><strong class="metric">{m['synthetic_room_count']} 个</strong><p>局部窗后办公室单元，含家具与灯位；不等于现实房间数量。</p></article></div><p>启用报道给出137米；承建方回顾给出103米；数据库114米标为估算。保留冲突，沿用旧资料包137格作为可编辑试作范围，不把不同口径相加。楼板位置、建筑宽深和场地仍是估算。</p><table><tr><th>类别</th><th>本版表达</th><th>边界</th></tr><tr><td>浅色花岗岩外观</td><td>石英、平滑石、局部平滑砂岩；半砖作细檐</td><td>材料映射，不认定现实使用石英</td></tr><tr><td>窗墙</td><td>实际洞口、后退玻璃片、窗台与房间背板</td><td>小于1格的窗框与分缝简化</td></tr><tr><td>普通房间灯</td><td>{counts['off']} 个不设灯 / {counts['glowstone']} 个荧石 / {counts['sea_lantern']} 个海晶灯</td><td>稳定ID和种子；50/25/25概率，非真实占用情况</td></tr><tr><td>固定照明</td><td>入口、钟室下沿、场地；针端小红灯</td><td>无可信同楼夜景，属于游戏方案</td></tr><tr><td>屋面</td><td>灰色为主，后侧局部绿灰代理</td><td>绿灰代理不等于真实铜板或草坪</td></tr></table>''')
    rows=sorted(csv.DictReader(materials.splitlines()),key=lambda r:int(r['count']),reverse=True)
    tab=''.join(f'<tr><td>{html.escape(r["block_id"].removeprefix("minecraft:"))}</td><td>{int(r["count"]):,}</td></tr>' for r in rows[:12])
